#!/bin/bash\n\n# EZBI Analytics Rollback Script\n# This script handles rolling back deployments to previous versions\n\nset -euo pipefail\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Default values\nENVIRONMENT=\"staging\"\nNAMESPACE=\"ezbi-analytics\"\nDRY_RUN=false\nVERBOSE=false\nROLLBACK_STEPS=1\nFORCE_ROLLBACK=false\n\n# Function to print colored output\nprint_status() {\n    echo -e \"${BLUE}[INFO]${NC} $1\"\n}\n\nprint_success() {\n    echo -e \"${GREEN}[SUCCESS]${NC} $1\"\n}\n\nprint_warning() {\n    echo -e \"${YELLOW}[WARNING]${NC} $1\"\n}\n\nprint_error() {\n    echo -e \"${RED}[ERROR]${NC} $1\"\n}\n\n# Function to show usage\nshow_usage() {\n    cat << EOF\nUsage: $0 [OPTIONS] <environment>\n\nEnvironments:\n  development    Rollback development environment\n  staging        Rollback staging environment\n  production     Rollback production environment\n\nOptions:\n  -n, --namespace NAMESPACE    Kubernetes namespace (default: ezbi-analytics)\n  -s, --steps STEPS           Number of rollback steps (default: 1)\n  -d, --dry-run               Show what would be rolled back without actually rolling back\n  -v, --verbose               Enable verbose output\n  -f, --force                 Force rollback without confirmation\n  -h, --help                  Show this help message\n\nExamples:\n  $0 staging\n  $0 production --steps 2 --dry-run\n  $0 staging --force --verbose\n\nEOF\n}\n\n# Function to check prerequisites\ncheck_prerequisites() {\n    print_status \"Checking prerequisites...\"\n    \n    # Check if kubectl is installed\n    if ! command -v kubectl &> /dev/null; then\n        print_error \"kubectl is not installed. Please install kubectl first.\"\n        exit 1\n    fi\n    \n    # Check kubectl connection\n    if ! kubectl cluster-info &> /dev/null; then\n        print_error \"Cannot connect to Kubernetes cluster. Please check your kubeconfig.\"\n        exit 1\n    fi\n    \n    # Check if namespace exists\n    if ! kubectl get namespace \"$NAMESPACE\" &> /dev/null; then\n        print_error \"Namespace $NAMESPACE does not exist.\"\n        exit 1\n    fi\n    \n    print_success \"Prerequisites check passed\"\n}\n\n# Function to get rollout history\nget_rollout_history() {\n    local deployment=$1\n    print_status \"Getting rollout history for $deployment...\"\n    \n    if [[ \"$VERBOSE\" == \"true\" ]]; then\n        kubectl rollout history deployment/\"$deployment\" -n \"$NAMESPACE\"\n    else\n        kubectl rollout history deployment/\"$deployment\" -n \"$NAMESPACE\" --revision=0\n    fi\n}\n\n# Function to show current deployment status\nshow_current_status() {\n    print_status \"Current deployment status:\"\n    \n    local deployments=(\n        \"backend-deployment\"\n        \"frontend-deployment\"\n        \"ml-engine-deployment\"\n    )\n    \n    for deployment in \"${deployments[@]}\"; do\n        if kubectl get deployment \"$deployment\" -n \"$NAMESPACE\" &> /dev/null; then\n            echo \"\\n=== $deployment ===\"\n            kubectl get deployment \"$deployment\" -n \"$NAMESPACE\" -o wide\n            \n            if [[ \"$VERBOSE\" == \"true\" ]]; then\n                get_rollout_history \"$deployment\"\n            fi\n        else\n            print_warning \"Deployment $deployment not found\"\n        fi\n    done\n}\n\n# Function to create backup before rollback\ncreate_backup() {\n    if [[ \"$ENVIRONMENT\" == \"development\" ]]; then\n        print_status \"Skipping backup for development environment\"\n        return 0\n    fi\n    \n    print_status \"Creating backup before rollback...\"\n    \n    # Create timestamp for backup\n    local timestamp=$(date +\"%Y%m%d_%H%M%S\")\n    local backup_name=\"ezbi_rollback_backup_${ENVIRONMENT}_${timestamp}\"\n    \n    # Create backup directory if it doesn't exist\n    mkdir -p backups\n    \n    # Database backup\n    print_status \"Creating database backup...\"\n    if kubectl get deployment postgres-deployment -n \"$NAMESPACE\" &> /dev/null; then\n        kubectl exec -n \"$NAMESPACE\" deployment/postgres-deployment -- pg_dump -U ezbi_user ezbi_analytics > \"backups/${backup_name}_db.sql\"\n        print_success \"Database backup created: backups/${backup_name}_db.sql\"\n    else\n        print_warning \"PostgreSQL deployment not found, skipping database backup\"\n    fi\n    \n    # Redis backup\n    print_status \"Creating Redis backup...\"\n    if kubectl get deployment redis-deployment -n \"$NAMESPACE\" &> /dev/null; then\n        kubectl exec -n \"$NAMESPACE\" deployment/redis-deployment -- redis-cli BGSAVE\n        print_success \"Redis backup initiated\"\n    else\n        print_warning \"Redis deployment not found, skipping Redis backup\"\n    fi\n    \n    print_success \"Backup created: $backup_name\"\n}\n\n# Function to rollback deployment\nrollback_deployment() {\n    local deployment=$1\n    print_status \"Rolling back $deployment...\"\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        print_status \"Would rollback $deployment by $ROLLBACK_STEPS steps\"\n        return 0\n    fi\n    \n    # Get current revision\n    local current_revision\n    current_revision=$(kubectl get deployment \"$deployment\" -n \"$NAMESPACE\" -o jsonpath='{.metadata.annotations.deployment\\.kubernetes\\.io/revision}')\n    \n    # Calculate target revision\n    local target_revision=$((current_revision - ROLLBACK_STEPS))\n    \n    if [[ $target_revision -lt 1 ]]; then\n        print_error \"Cannot rollback $ROLLBACK_STEPS steps. Not enough revisions.\"\n        return 1\n    fi\n    \n    print_status \"Rolling back from revision $current_revision to revision $target_revision\"\n    \n    # Perform rollback\n    if kubectl rollout undo deployment/\"$deployment\" -n \"$NAMESPACE\" --to-revision=\"$target_revision\"; then\n        print_success \"Rollback initiated for $deployment\"\n        \n        # Wait for rollback to complete\n        print_status \"Waiting for rollback to complete...\"\n        if kubectl rollout status deployment/\"$deployment\" -n \"$NAMESPACE\" --timeout=300s; then\n            print_success \"Rollback completed for $deployment\"\n        else\n            print_error \"Rollback failed for $deployment\"\n            return 1\n        fi\n    else\n        print_error \"Failed to initiate rollback for $deployment\"\n        return 1\n    fi\n}\n\n# Function to rollback all deployments\nrollback_all_deployments() {\n    print_status \"Rolling back all deployments...\"\n    \n    local deployments=(\n        \"backend-deployment\"\n        \"frontend-deployment\"\n        \"ml-engine-deployment\"\n    )\n    \n    local failed_rollbacks=()\n    \n    for deployment in \"${deployments[@]}\"; do\n        if kubectl get deployment \"$deployment\" -n \"$NAMESPACE\" &> /dev/null; then\n            if ! rollback_deployment \"$deployment\"; then\n                failed_rollbacks+=(\"$deployment\")\n            fi\n        else\n            print_warning \"Deployment $deployment not found, skipping\"\n        fi\n    done\n    \n    if [[ ${#failed_rollbacks[@]} -gt 0 ]]; then\n        print_error \"Failed to rollback the following deployments: ${failed_rollbacks[*]}\"\n        return 1\n    fi\n    \n    print_success \"All deployments rolled back successfully\"\n}\n\n# Function to run health checks after rollback\nrun_health_checks() {\n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        print_status \"Skipping health checks (dry run mode)\"\n        return 0\n    fi\n    \n    print_status \"Running health checks after rollback...\"\n    \n    # Wait a bit for services to be ready\n    sleep 30\n    \n    # Check backend health\n    print_status \"Checking backend health...\"\n    if kubectl exec -n \"$NAMESPACE\" deployment/backend-deployment -- curl -f http://localhost:8000/health &> /dev/null; then\n        print_success \"Backend health check passed\"\n    else\n        print_error \"Backend health check failed\"\n        return 1\n    fi\n    \n    # Check ML engine health\n    print_status \"Checking ML engine health...\"\n    if kubectl exec -n \"$NAMESPACE\" deployment/ml-engine-deployment -- curl -f http://localhost:8001/health &> /dev/null; then\n        print_success \"ML engine health check passed\"\n    else\n        print_error \"ML engine health check failed\"\n        return 1\n    fi\n    \n    # Check frontend health\n    print_status \"Checking frontend health...\"\n    if kubectl exec -n \"$NAMESPACE\" deployment/frontend-deployment -- curl -f http://localhost:3000/api/health &> /dev/null; then\n        print_success \"Frontend health check passed\"\n    else\n        print_error \"Frontend health check failed\"\n        return 1\n    fi\n    \n    print_success \"All health checks passed\"\n}\n\n# Function to show post-rollback status\nshow_post_rollback_status() {\n    print_status \"Post-rollback status:\"\n    \n    echo \"\\n=== PODS ===\"\n    kubectl get pods -n \"$NAMESPACE\" -o wide\n    \n    echo \"\\n=== SERVICES ===\"\n    kubectl get services -n \"$NAMESPACE\"\n    \n    echo \"\\n=== DEPLOYMENTS ===\"\n    kubectl get deployments -n \"$NAMESPACE\" -o wide\n    \n    if [[ \"$VERBOSE\" == \"true\" ]]; then\n        echo \"\\n=== EVENTS ===\"\n        kubectl get events -n \"$NAMESPACE\" --sort-by=.metadata.creationTimestamp | tail -20\n    fi\n}\n\n# Function to confirm rollback\nconfirm_rollback() {\n    if [[ \"$FORCE_ROLLBACK\" == \"true\" ]] || [[ \"$DRY_RUN\" == \"true\" ]]; then\n        return 0\n    fi\n    \n    print_warning \"You are about to rollback the $ENVIRONMENT environment by $ROLLBACK_STEPS steps.\"\n    print_warning \"This action cannot be easily undone.\"\n    \n    echo -n \"Are you sure you want to continue? (yes/no): \"\n    read -r response\n    \n    if [[ \"$response\" != \"yes\" ]]; then\n        print_status \"Rollback cancelled by user\"\n        exit 0\n    fi\n}\n\n# Function to send notifications\nsend_notifications() {\n    local status=$1\n    local message=\"Rollback $status for $ENVIRONMENT environment\"\n    \n    # Send Slack notification if webhook URL is set\n    if [[ -n \"${SLACK_WEBHOOK_URL:-}\" ]]; then\n        local color=\"good\"\n        if [[ \"$status\" == \"failed\" ]]; then\n            color=\"danger\"\n        fi\n        \n        curl -X POST -H 'Content-type: application/json' \\\n            --data \"{\\\"text\\\":\\\"$message\\\", \\\"color\\\":\\\"$color\\\"}\" \\\n            \"$SLACK_WEBHOOK_URL\" || true\n    fi\n    \n    # Send email notification if configured\n    if [[ -n \"${EMAIL_NOTIFICATIONS:-}\" ]]; then\n        echo \"$message\" | mail -s \"EZBI Analytics Rollback $status\" \"$EMAIL_NOTIFICATIONS\" || true\n    fi\n}\n\n# Function to cleanup on exit\ncleanup() {\n    print_status \"Cleaning up...\"\n    # Remove any temporary files\n    rm -f /tmp/*.yaml\n}\n\n# Main rollback function\nmain() {\n    # Parse command line arguments\n    while [[ $# -gt 0 ]]; do\n        case $1 in\n            -n|--namespace)\n                NAMESPACE=\"$2\"\n                shift 2\n                ;;\n            -s|--steps)\n                ROLLBACK_STEPS=\"$2\"\n                shift 2\n                ;;\n            -d|--dry-run)\n                DRY_RUN=true\n                shift\n                ;;\n            -v|--verbose)\n                VERBOSE=true\n                shift\n                ;;\n            -f|--force)\n                FORCE_ROLLBACK=true\n                shift\n                ;;\n            -h|--help)\n                show_usage\n                exit 0\n                ;;\n            -*)\n                print_error \"Unknown option: $1\"\n                show_usage\n                exit 1\n                ;;\n            *)\n                ENVIRONMENT=\"$1\"\n                shift\n                ;;\n        esac\n    done\n    \n    # Validate environment\n    if [[ ! \"$ENVIRONMENT\" =~ ^(development|staging|production)$ ]]; then\n        print_error \"Invalid environment: $ENVIRONMENT\"\n        show_usage\n        exit 1\n    fi\n    \n    # Validate rollback steps\n    if [[ ! \"$ROLLBACK_STEPS\" =~ ^[0-9]+$ ]] || [[ $ROLLBACK_STEPS -lt 1 ]]; then\n        print_error \"Invalid rollback steps: $ROLLBACK_STEPS\"\n        exit 1\n    fi\n    \n    # Set up trap for cleanup\n    trap cleanup EXIT\n    \n    print_status \"Starting rollback for $ENVIRONMENT environment (steps: $ROLLBACK_STEPS)...\"\n    \n    # Run rollback steps\n    check_prerequisites\n    show_current_status\n    confirm_rollback\n    \n    if [[ \"$DRY_RUN\" == \"false\" ]]; then\n        create_backup\n    fi\n    \n    if rollback_all_deployments; then\n        run_health_checks\n        \n        if [[ \"$VERBOSE\" == \"true\" ]]; then\n            show_post_rollback_status\n        fi\n        \n        print_success \"Rollback completed successfully!\"\n        send_notifications \"succeeded\"\n        \n        # Show access information\n        case $ENVIRONMENT in\n            development)\n                print_status \"Access your application at: http://localhost:3000\"\n                ;;\n            staging)\n                print_status \"Access your application at: https://staging.ezbi.example.com\"\n                ;;\n            production)\n                print_status \"Access your application at: https://ezbi.example.com\"\n                ;;\n        esac\n    else\n        print_error \"Rollback failed!\"\n        send_notifications \"failed\"\n        exit 1\n    fi\n}\n\n# Run main function\nmain \"$@\""